content:
r = piv_encode_apdu(card, plain, *sm_apdu);
        if (r < 0 && *sm_apdu) {
                piv_free_sm_apdu(card, NULL, sm_apdu);
        }

        LOG_FUNC_RETURN(card->ctx, r);
}


/* ASN1 callback to save address and len of the object */
static int piv_get_asn1_obj(sc_context_t *ctx, void *arg,  const u8 *obj, size_t len, int depth)
{
        struct sc_lv_data *al = arg;

        if (!arg)
                return SC_ERROR_INTERNAL;

        al->value = (u8 *)obj;
        al->len = len;
        return SC_SUCCESS;
}

static int piv_decode_apdu(sc_card_t *card, sc_apdu_t *plain, sc_apdu_t *sm_apdu)
{
        int r = SC_SUCCESS;
        int i;

        /* Get PIN */
        if (!(pin = extract_word(&data, &size)))
                goto end;

        if (fill_key_template(&key_template, &n_key_attr, &data, &size, &class, true) != 0)
                goto end;

        if (size < 3)
                goto end;
        if (data[0] && n_key_attr < 20) {
                data++; size--;
                ptr = data;
                if ((contents_len = get_buffer(&ptr, size, &data, &size, 5000)) == 0)
                        goto end;
                memcpy(contents, ptr, contents_len);
                FILL_ATTR(key_template[n_key_attr], CKA_VALUE, contents, contents_len);
                n_key_attr++;
        }

        /* Initialize */
        if (fuzz_pkcs11_initialize(data, size, NULL, &session) != CKR_OK)
                goto end;

        p11->C_Login(session, login_type, (CK_UTF8CHAR *) pin, strlen(pin));
        p11->C_CreateObject(session, key_template, n_key_attr, &key_obj);
        p11->C_CloseSession(session);
        p11->C_Finalize(NULL);
end:
        free(pin);
        free(key_template);
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
        uint8_t operation = 0;
        void (*func_ptr[])(const uint8_t*, size_t) = {
                test_change_pin,
                test_init_pin,
                test_init_token,
                test_random,
                test_digest_update,
                test_digest,
                test_sign,
                test_verify,
                test_decrypt,
                test_wrap,
                test_unwrap,
                test_derive,
                test_genkeypair,
                test_store_data,
                test_store_cert,
                test_store_key
        };

        if (size < 10)
                return 0;

        operation = *data % 16;
        data++;
        size--;

        func_ptr[operation](data, size);

        return 0;
}
